package com.girlshop.service;
import com.fasterxml.jackson.databind.JsonNode;
import com.girlshop.dto.Result;
import com.girlshop.utils.UserHolder;
import org.springframework.stereotype.Service;
import org.springframework.context.annotation.DependsOn;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;
import javax.annotation.Resource;
import java.util.*;
@Service @DependsOn("prioritySchema")
public class PlatformImprovementService {
 @org.springframework.beans.factory.annotation.Value("${platform.workers.enabled:true}") private boolean improvementWorkers=true;

 @Resource private JdbcTemplate jdbc; @Resource private TradeExperienceService trade; @Resource private CacheEvictionService evictions;
 @Value("${shop.admin.ids:}") private String admins="";
 private long me(){if(UserHolder.getUser()==null)throw new IllegalArgumentException("请先登录");return UserHolder.getUser().getId();}
 public boolean admin(){long id=me();return Arrays.stream(admins.split(",")).map(String::trim).anyMatch(s->s.equals(Long.toString(id)));}
 private void requireAdmin(){if(!admin())throw new IllegalArgumentException("需要管理员权限，请配置服务端shop.admin.ids");}
 public Result access(){return Result.ok(Collections.singletonMap("admin",admin()));}
 public Result preferences(){List<Integer> p=jdbc.queryForList("SELECT price_enabled FROM tb_notice_preference WHERE user_id=?",Integer.class,me());return Result.ok(Collections.singletonMap("priceEnabled",p.isEmpty()||p.get(0)==1));}
 @Transactional public Result preferences(JsonNode b){if(!b.path("priceEnabled").isBoolean())throw new IllegalArgumentException("请选择提醒状态");jdbc.update("INSERT INTO tb_notice_preference(user_id,price_enabled) VALUES(?,?) ON DUPLICATE KEY UPDATE price_enabled=VALUES(price_enabled)",me(),b.path("priceEnabled").asBoolean()?1:0);return preferences();}
 @Transactional @Scheduled(fixedDelayString="${alerts.scan-ms:60000}") public void alerts(){if(!improvementWorkers)return;
  // Persisted observation prevents repeated alerts after restarts. Product edits also synchronize this snapshot.
  jdbc.update("DELETE a FROM tb_product_alert a LEFT JOIN tb_favorite f ON f.user_id=a.user_id AND f.product_id=a.product_id WHERE f.id IS NULL");
  jdbc.update("INSERT IGNORE INTO tb_product_alert(user_id,product_id,last_price,last_status) SELECT f.user_id,f.product_id,p.price,p.status FROM tb_favorite f JOIN tb_product p ON p.id=f.product_id LEFT JOIN tb_product_alert a ON a.user_id=f.user_id AND a.product_id=f.product_id WHERE a.product_id IS NULL LIMIT 1000");
  for(Map<String,Object> p:jdbc.queryForList("SELECT a.user_id,a.product_id,a.last_price,a.last_status,p.title,p.price,p.status,COALESCE(n.price_enabled,1) enabled FROM tb_product_alert a JOIN tb_product p ON p.id=a.product_id LEFT JOIN tb_notice_preference n ON n.user_id=a.user_id WHERE p.price<>a.last_price OR p.status<>a.last_status LIMIT 100 FOR UPDATE")){
   long user=((Number)p.get("user_id")).longValue(),product=((Number)p.get("product_id")).longValue();boolean price=new java.math.BigDecimal(p.get("price").toString()).compareTo(new java.math.BigDecimal(p.get("last_price").toString()))<0;boolean live=((Number)p.get("status")).intValue()==1;
   if(((Number)p.get("enabled")).intValue()==1&&live&&(price||((Number)p.get("last_status")).intValue()!=1))trade.productNotice(user,price?"收藏商品降价":"收藏商品重新上架",p.get("title")+"，当前价格¥"+p.get("price"),product);
   jdbc.update("UPDATE tb_product_alert SET last_price=?,last_status=? WHERE user_id=? AND product_id=?",p.get("price"),p.get("status"),user,product);
  }
 }
 public Result credit(long seller){Map<String,Object> data=new LinkedHashMap<>();data.put("completedOrders",jdbc.queryForObject("SELECT COUNT(*) FROM tb_order WHERE seller_id=? AND status=3",Long.class,seller));data.put("reviews",jdbc.queryForObject("SELECT COUNT(*) FROM tb_review r JOIN tb_order o ON o.id=r.order_id WHERE o.seller_id=?",Long.class,seller));data.put("averageScore",jdbc.queryForObject("SELECT ROUND(AVG(r.score),1) FROM tb_review r JOIN tb_order o ON o.id=r.order_id WHERE o.seller_id=?",Double.class,seller));return Result.ok(data);}
 @Transactional public Result feedback(long draft,JsonNode b){List<Map<String,Object>> jobs=jdbc.queryForList("SELECT j.id FROM tb_ai_listing_job j JOIN tb_product_draft d ON d.id=j.draft_id WHERE d.id=? AND d.user_id=? AND j.status='READY' ORDER BY j.created_at DESC LIMIT 1",draft,me());if(jobs.isEmpty())throw new IllegalArgumentException("没有可反馈的本人生成草稿");String rating=b.path("rating").asText(),reason=b.path("reason").asText("").trim();if(!Arrays.asList("HELPFUL","INCORRECT","INCOMPLETE").contains(rating)||reason.length()>500)throw new IllegalArgumentException("请选择反馈类型，说明最多500字");jdbc.update("INSERT INTO tb_ai_feedback(user_id,draft_id,job_id,rating,reason) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),reason=VALUES(reason)",me(),draft,jobs.get(0).get("id"),rating,reason);return Result.ok();}
 public Result health(){requireAdmin();Map<String,Object> result=new LinkedHashMap<>();try{result.put("database",jdbc.queryForObject("SELECT 1",Integer.class)==1);}catch(Exception e){result.put("database",false);}for(int port:new int[]{6379,5672,8090}){try(java.net.Socket socket=new java.net.Socket()){socket.connect(new java.net.InetSocketAddress("127.0.0.1",port),1000);result.put(String.valueOf(port),true);}catch(Exception e){result.put(String.valueOf(port),false);}}return Result.ok(result);}
 public Result dashboard(){requireAdmin();Map<String,Object> d=new LinkedHashMap<>();d.put("noticeDelivery",jdbc.queryForList("SELECT status,COUNT(*) total FROM tb_notice_outbox GROUP BY status"));d.put("aiTasks",jdbc.queryForList("SELECT status,COUNT(*) total,ROUND(AVG(TIMESTAMPDIFF(SECOND,created_at,updated_at)),1) seconds FROM tb_ai_listing_job WHERE created_at>DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY status"));d.put("aiFeedback",jdbc.queryForList("SELECT rating,COUNT(*) total FROM tb_ai_feedback GROUP BY rating"));d.put("aiEditedFields",jdbc.queryForList("SELECT field_name field,COUNT(*) drafts,SUM(edits) total FROM tb_ai_field_edit GROUP BY field_name"));d.put("pendingFlash",jdbc.queryForObject("SELECT COUNT(*) FROM tb_flash_request WHERE status='PENDING'",Integer.class));return Result.ok(d);}
 public Result list(String kind,int page){requireAdmin();int offset=(Math.max(1,Math.min(page,10000))-1)*20;String sql;if("reports".equals(kind))sql="SELECT CAST(id AS CHAR) id,CAST(target_id AS CHAR) targetId,target_type targetType,reason,images,status,result FROM tb_trade_report ORDER BY id DESC";else if("cases".equals(kind))sql="SELECT CAST(id AS CHAR) id,CAST(order_id AS CHAR) orderId,reason,images,status,reply FROM tb_after_sale WHERE status='DISPUTED' ORDER BY id DESC";else if("delivery".equals(kind))sql="SELECT CAST(product_id AS CHAR) id,status,attempts,last_error lastError,created_at createdAt FROM tb_notice_outbox ORDER BY created_at DESC";else if("products".equals(kind))sql="SELECT CAST(id AS CHAR) id,title,description,status FROM tb_product ORDER BY id DESC";else if("users".equals(kind))sql="SELECT CAST(u.id AS CHAR) id,u.nick_name title,IF(r.user_id IS NULL,'ACTIVE','BANNED') status,r.reason description FROM tb_user u LEFT JOIN tb_account_restriction r ON r.user_id=u.id ORDER BY u.id DESC";else if("audit".equals(kind))sql="SELECT CAST(id AS CHAR) id,CAST(actor_id AS CHAR) actorId,kind,CAST(target_id AS CHAR) targetId,action,note,created_at createdAt FROM tb_admin_audit ORDER BY id DESC";else throw new IllegalArgumentException("未知列表");return Result.ok(jdbc.queryForList(sql+" LIMIT 20 OFFSET ?",offset));}
 @Transactional public Result action(String kind,long id,JsonNode b){requireAdmin();String action=b.path("action").asText(),note=b.path("note").asText("").trim();if(note.isEmpty()||note.length()>900)throw new IllegalArgumentException("请填写1至900字处理说明");
  if("reports".equals(kind)){if(!Arrays.asList("UPHELD","DISMISSED").contains(action))throw new IllegalArgumentException("无效处理结果");List<Map<String,Object>> rows=jdbc.queryForList("SELECT * FROM tb_trade_report WHERE id=? FOR UPDATE",id);if(rows.isEmpty()||!"PENDING".equals(rows.get(0).get("status")))throw new IllegalArgumentException("举报已处理或不存在");jdbc.update("UPDATE tb_trade_report SET status=?,result=? WHERE id=?",action,note,id);trade.notice(((Number)rows.get(0).get("user_id")).longValue(),"举报处理结果",note,null);}
  else if("cases".equals(kind)){if(!Arrays.asList("RETURN_REQUIRED","REJECTED").contains(action))throw new IllegalArgumentException("请选择退货处理或驳回争议");List<Map<String,Object>> rows=jdbc.queryForList("SELECT * FROM tb_after_sale WHERE id=? FOR UPDATE",id);if(rows.isEmpty()||!"DISPUTED".equals(rows.get(0).get("status")))throw new IllegalArgumentException("争议状态已变化");Map<String,Object> c=rows.get(0);jdbc.update("UPDATE tb_after_sale SET status=?,reply=?,updated_at=NOW() WHERE id=?",action,note,id);jdbc.update("INSERT INTO tb_after_sale_event(case_id,actor_id,action,note) VALUES(?,?,'ADMIN_MEDIATION',?)",id,me(),note);trade.notice(((Number)c.get("buyer_id")).longValue(),"售后争议处理",note,((Number)c.get("order_id")).longValue());trade.notice(((Number)c.get("seller_id")).longValue(),"售后争议处理",note,((Number)c.get("order_id")).longValue());}
  else if("users".equals(kind)&&Arrays.asList("BAN","UNBAN").contains(action)){if(id==me()||Arrays.stream(admins.split(",")).map(String::trim).anyMatch(v->v.equals(Long.toString(id))))throw new IllegalArgumentException("不能限制管理员账号");if(jdbc.queryForObject("SELECT COUNT(*) FROM tb_user WHERE id=?",Integer.class,id)==0)throw new IllegalArgumentException("用户不存在");if("BAN".equals(action))jdbc.update("INSERT INTO tb_account_restriction(user_id,reason) VALUES(?,?) ON DUPLICATE KEY UPDATE reason=VALUES(reason)",id,note);else jdbc.update("DELETE FROM tb_account_restriction WHERE user_id=?",id);}
  else if("products".equals(kind)&&"TAKEDOWN".equals(action)){if(jdbc.update("UPDATE tb_product SET status=0 WHERE id=? AND status=1",id)!=1)throw new IllegalArgumentException("商品状态已变化");evictions.enqueue(id);}
  else if("delivery".equals(kind)&&"RETRY".equals(action)){if(jdbc.update("UPDATE tb_notice_outbox SET status='PENDING',attempts=0,next_at=NOW() WHERE product_id=? AND status='DEAD'",id)!=1)throw new IllegalArgumentException("只允许重试失败归档的消息");}
  else throw new IllegalArgumentException("无效操作");jdbc.update("INSERT INTO tb_admin_audit(actor_id,kind,target_id,action,note) VALUES(?,?,?,?,?)",me(),kind,id,action,note);return Result.ok();
 }
}
